<?php
declare(strict_types=1);

require_once __DIR__ . '/../includes/functions.php';
requireAdminPermission('dashboard.view');

$admin = getCurrentAdmin();
$totalUsers = getStatCount('users');
$totalApplications = getStatCount('applications');
$newApplications = (int)(dbFetchOne("SELECT COUNT(*) AS count FROM applications WHERE status = 'new'")['count'] ?? 0);
$totalPortfolio = getStatCount('portfolio');
$totalBlog = (int)(dbFetchOne("SELECT COUNT(*) AS count FROM blog_posts WHERE status = 'published'")['count'] ?? 0);
$recentApplications = dbFetchAll("SELECT a.*, u.full_name AS user_name, u.phone AS user_phone, s.title_uz AS service_title FROM applications a LEFT JOIN users u ON a.user_id = u.id LEFT JOIN services s ON a.service_id = s.id ORDER BY a.created_at DESC LIMIT 10");
$links = [
    ['dashboard.php', '📊 Dashboard', 'dashboard.view'],
    ['services.php', '🛠 Xizmatlar', 'services.view'],
    ['portfolio.php', '📁 Portfolio', 'portfolio.view'],
    ['blog.php', '📝 Blog', 'blog.view'],
    ['applications.php', '📋 Arizalar', 'applications.view'],
    ['users.php', '👥 Foydalanuvchilar', 'users.view'],
    ['chat.php', '💬 Chat', 'chat.view'],
    ['branding.php', '🎨 Brending', 'branding.manage'],
    ['settings.php', '⚙ Sozlamalar', 'settings.manage']
];
$statusLabels = ['new'=>'Yangi','in_review'=>"Ko'rib chiqilmoqda",'contacted'=>'Bog‘lanildi','approved'=>'Tasdiqlandi','rejected'=>'Rad etildi','completed'=>'Yakunlandi','cancelled'=>'Bekor qilindi'];
?>
<!doctype html>
<html lang="uz"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Dashboard — SOON Admin</title><link rel="stylesheet" href="../assets/css/main.css"><style>body{background:var(--bg-secondary)}.layout{display:grid;grid-template-columns:250px 1fr;min-height:100vh}.side{background:var(--bg-primary);border-right:1px solid var(--border-color);padding:24px;position:sticky;top:0;height:100vh;box-sizing:border-box}.logo{font-size:1.5rem;font-weight:800;color:var(--primary);text-decoration:none;display:block;margin-bottom:28px}.nav{display:grid;gap:7px}.nav a{padding:11px 13px;border-radius:12px;color:var(--text-secondary);text-decoration:none}.nav a:hover{background:var(--bg-secondary);color:var(--text-primary)}.main{padding:32px;min-width:0}.head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.muted{color:var(--text-muted)}.stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;margin-bottom:24px}.card{background:var(--bg-primary);border:1px solid var(--border-color);border-radius:18px;padding:22px}.value{font-size:2rem;font-weight:800;color:var(--primary)}.label{color:var(--text-muted);margin-top:5px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:700px}th,td{text-align:left;padding:12px;border-bottom:1px solid var(--border-color)}th{color:var(--text-muted);font-size:.85rem}.badge{display:inline-block;padding:5px 10px;border-radius:999px;background:var(--bg-secondary);font-size:.82rem}.user{display:flex;gap:10px;align-items:center}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:var(--primary);color:#fff;font-weight:700}@media(max-width:900px){.layout{grid-template-columns:1fr}.side{position:static;height:auto;border-right:0;border-bottom:1px solid var(--border-color)}.nav{display:flex;overflow:auto}.nav a{white-space:nowrap}.main{padding:18px}.head{align-items:flex-start;flex-direction:column}}</style></head><body><div class="layout"><aside class="side"><a class="logo" href="dashboard.php">SOON Admin</a><nav class="nav"><?php foreach($links as $link): if(adminHasPermission($link[2],$admin)): ?><a href="<?php echo e($link[0]); ?>"><?php echo e($link[1]); ?></a><?php endif; endforeach; ?><a href="../index.php" target="_blank">🌐 Saytni ko‘rish</a><a href="logout.php">🚪 Chiqish</a></nav></aside><main class="main"><header class="head"><div><div class="muted">SOON boshqaruv paneli</div><h1 style="margin:.25rem 0">Dashboard</h1><div class="muted">Xush kelibsiz, <?php echo e($admin['full_name'] ?? $admin['username'] ?? 'Admin'); ?></div></div><button data-theme-toggle class="btn btn-secondary">🌓 Mavzu</button></header><section class="stats"><div class="card"><div class="value"><?php echo $totalUsers; ?></div><div class="label">Foydalanuvchilar</div></div><div class="card"><div class="value"><?php echo $totalApplications; ?></div><div class="label">Jami arizalar</div></div><div class="card"><div class="value"><?php echo $newApplications; ?></div><div class="label">Yangi arizalar</div></div><div class="card"><div class="value"><?php echo $totalPortfolio; ?></div><div class="label">Portfolio</div></div><div class="card"><div class="value"><?php echo $totalBlog; ?></div><div class="label">Nashr qilingan blog</div></div></section><section class="card"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:18px"><h2 style="margin:0">Oxirgi arizalar</h2><?php if(adminHasPermission('applications.view',$admin)): ?><a class="btn btn-secondary btn-sm" href="applications.php">Barchasi →</a><?php endif; ?></div><?php if(!$recentApplications): ?><p class="muted" style="text-align:center;padding:35px 0">Hozircha arizalar yo‘q.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Foydalanuvchi</th><th>Xizmat</th><th>Holat</th><th>Sana</th></tr></thead><tbody><?php foreach($recentApplications as $app): ?><tr><td><div class="user"><span class="avatar"><?php echo e(mb_strtoupper(mb_substr((string)($app['user_name'] ?? 'A'),0,1))); ?></span><span><strong><?php echo e($app['user_name'] ?? 'Noma’lum'); ?></strong><br><small class="muted"><?php echo e($app['user_phone'] ?? ''); ?></small></span></div></td><td><?php echo e($app['service_title'] ?? 'Xizmat'); ?></td><td><span class="badge"><?php echo e($statusLabels[$app['status']] ?? $app['status']); ?></span></td><td><?php echo e(date('d.m.Y H:i',strtotime($app['created_at']))); ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></main></div><script src="../assets/js/main.js"></script></body></html>
